/*
 * phypara serialization order (docsClean/09 and appendix-phypara-order):
 * 69 segments, 5170 halfwords. Table generated by tools/gen_phypara.py --fw.
 */
#ifndef COMMON_PHYPARA_H
#define COMMON_PHYPARA_H

#include <stdint.h>

#define PHYPARA_NSEG	69
#define PHYPARA_COUNT	5170

struct phypara_seg {
	uint32_t base;		/* PHY CSR index of the segment base */
	uint16_t count;		/* halfwords in the segment */
	uint16_t arg;		/* sequential: first offset; sparse: index into phypara_offsets */
	uint8_t seq;		/* 1 = sequential */
};

extern const struct phypara_seg phypara_segs[PHYPARA_NSEG];
extern const uint16_t phypara_offsets[];

/* PHY CSR index of serialized position k within segment s */
static inline uint32_t phypara_index(const struct phypara_seg *s, uint16_t j)
{
	return s->base + (s->seq ? (uint32_t)s->arg + j : phypara_offsets[s->arg + j]);
}

#endif
